#include "data_ring_contract.h"
#include <cstdio>
#include <cstdlib>
#include <algorithm>

void require(bool value, const char* label) {
  if (!value) { std::fprintf(stderr, "FAIL %s\n", label); std::exit(1); }
}
int main() {
  using namespace bridge_data;
  uint64_t cases = 0;
  for (uint32_t capacity=2; capacity<=67; ++capacity) {
    for (uint64_t begin=0; begin<capacity*8; ++begin) {
      for (uint64_t n=0; n<=capacity+1; ++n) {
        for (bool blob : {false,true}) {
          auto r=plan(begin,capacity,n,blob);
          if (!r.valid) { continue; }
          require(r.end-begin==r.words && r.words<=capacity,"occupied span");
          if (blob) { require(static_cast<uint64_t>(r.payload)+n-1<=capacity,"contiguous payload"); }
          for (uint64_t consumed=begin>capacity?begin-capacity:0; consumed<=begin; ++consumed) {
            const bool expected=r.words<=capacity-(begin-consumed);
            require(available(r.end,consumed,capacity)==expected,"no overwrite");
            ++cases;
          }
        }
      }
    }
  }
  require(!plan(UINT64_MAX,8,1,false).valid,"cursor overflow");
  require(!plan(UINT64_MAX-2,8,4,true).valid,"padding overflow");
  uint64_t words=0;
  require(blobWords(0,words) && words==1,"zero-length prefix");
  require(blobWords(UINT32_MAX,words) && words==1073741825ULL,"uint32 boundary");
  if (sizeof(size_t)>4) { require(!blobWords(static_cast<size_t>(UINT32_MAX)+1,words),"native to wire overflow"); }
  Control c{}; c.magic=Magic;c.version=Version;c.bytes=sizeof(c);c.capacity=8;
  require(compatible(c,8),"matching protocol");
  ++c.version;require(!compatible(c,8),"protocol rejection");--c.version;
  // Progress before registration: the second read sees it; no OS wait is needed.
  unsigned reads=0, waits=0;
  auto progress=[&](){ return ++reads==1?uint64_t(0):uint64_t(4); };
  require(waitForSpace(c,12,8,progress,[&](){++waits;return false;},[](){return true;}),"registration recheck");
  require(reads==2 && waits==0 && c.waiting.load()==0,"stale progress never blocks");
  // During/after registration, coalesced and duplicate tokens do not grant space.
  for(unsigned tokens=0;tokens<7;++tokens) {
    c.consumed=0;waits=0;
    require(waitForSpace(c,12,8,[&](){return c.consumed.load();},[&](){
      ++waits; if(waits==tokens+1){ c.consumed=4; } return true;
    },[](){return true;}),"eventual progress");
    require(waits==tokens+1,"spurious wake does not permit overwrite");
  }
  // Dropped notification: a bounded wait ends; the final condition wins.
  c.consumed=0;
  require(waitForSpace(c,12,8,[&](){return c.consumed.load();},[&](){c.consumed=4;return false;},[](){return true;}),"dropped wake recheck");
  c.consumed=0;
  require(!waitForSpace(c,12,8,[&](){return c.consumed.load();},[](){return false;},[](){return true;}),"timeout/stall");
  require(!waitForSpace(c,12,8,[](){return uint64_t(4);},[](){return true;},[](){return false;}),"peer exited");
  c.fault=1;
  require(!waitForSpace(c,4,8,[](){return uint64_t(0);},[](){return true;},[](){return true;}),"poison blocks fast path");
  std::printf("DATA_RING_CONTRACT_PASS checked_space_states=%llu pointer_bits=%u\n",
    static_cast<unsigned long long>(cases),static_cast<unsigned>(sizeof(void*)*8));
}
